{
  "constraints": [
    {
      "constraint": "画面主体必须是一艘大型海洋客运邮轮。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "船体下部应呈深色船壳，上层建筑应呈浅色，形成邮轮式明暗对比涂装。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "船体或上层建筑应呈现邮轮客运设施，如成排客舱舷窗、阳台或救生艇等。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "不得出现货船式集装箱堆场或大型货物吊机。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "不得出现军舰式舰炮或导弹发射装置。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "不得出现其他邮轮公司品牌标识或非“Disney Dream/迪士尼梦想号”的船名。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
